        var ifaddr: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&ifaddr) == 0 else { return nil }
        defer { freeifaddrs(ifaddr) }
        var utun: String?, wlan: String?, fallback: String?
        var p = ifaddr
        while let c = p {
            let name = String(cString: c.pointee.ifa_name)
            if c.pointee.ifa_addr?.pointee.sa_family == UInt8(AF_INET),
               let a: UnsafeMutablePointer<sockaddr> = c.pointee.ifa_addr! {
                var host = [CChar](repeating: 0, count: Int(NI_MAXHOST))
                if getnameinfo(a, socklen_t(a.pointee.sa_len), &host, socklen_t(host.count), nil, 0, NI_NUMERICHOST) == 0 {
                    let s = String(cString: host)
